import 'package:audioplayers/audioplayers.dart';

/// Sound effects and music. Every file lives in assets/audio (generated by
/// tools/gen_audio.py), so it all works offline. Any audio error is swallowed:
/// the game must never crash because of sound.
class Sfx {
  static bool enabled = true;
  static final List<AudioPlayer> _pool = [];
  static final Map<String, int> _last = {};
  static AudioPlayer? _music;
  static String? _track;
  static int _next = 0;
  static bool _ready = false;

  static Future<void> init() async {
    try {
      // Let effects and music play together without stealing audio focus.
      await AudioPlayer.global.setAudioContext(
          AudioContextConfig(focus: AudioContextConfigFocus.mixWithOthers).build());
      for (var i = 0; i < 6; i++) {
        _pool.add(AudioPlayer());
      }
      final m = AudioPlayer();
      await m.setReleaseMode(ReleaseMode.loop);
      _music = m;
      _ready = true;
    } catch (_) {
      _ready = false;
    }
  }

  static Future<void> play(String name, {double volume = 0.8}) async {
    if (!enabled || !_ready) return;
    try {
      final now = DateTime.now().millisecondsSinceEpoch;
      if (now - (_last[name] ?? 0) < 45) return; // avoid machine-gun repeats
      _last[name] = now;
      final p = _pool[_next];
      _next = (_next + 1) % _pool.length;
      await p.play(AssetSource('audio/$name.wav'), volume: volume);
    } catch (_) {}
  }

  static Future<void> music(String name, {double volume = 0.35}) async {
    _track = name;
    if (!_ready) return;
    try {
      final m = _music;
      if (m == null) return;
      await m.stop();
      if (!enabled) return;
      await m.play(AssetSource('audio/$name.wav'), volume: volume);
    } catch (_) {}
  }

  static Future<void> stopMusic() async {
    _track = null;
    try {
      await _music?.stop();
    } catch (_) {}
  }

  static Future<void> pauseMusic() async {
    try {
      await _music?.pause();
    } catch (_) {}
  }

  static Future<void> resumeMusic() async {
    if (!enabled || _track == null) return;
    try {
      await _music?.resume();
    } catch (_) {}
  }

  static void setEnabled(bool on) {
    enabled = on;
    final t = _track;
    if (!on) {
      pauseMusic();
    } else if (t != null) {
      music(t);
    }
  }
}
